# A plain T-005 summary line has no run field. Read with -Run left out, StallStacks must not report it as run 0 (T005Batch's first run).
$ErrorActionPreference = 'Stop'
$work = Join-Path ([System.IO.Path]::GetTempPath()) ("fsa-runfield-{0}" -f [guid]::NewGuid().ToString('N'))
[void][System.IO.Directory]::CreateDirectory($work)
$code = 1
try {
    $summary = Join-Path $work 'runs.jsonl'
    '{"uiThread":1,"primaryPhase":"scan","exitReason":"closed","phases":[{"name":"scan","reached":true,"longestWaitMs":85},{"name":"rescan","reached":false,"longestWaitMs":0}]}' |
        Set-Content -LiteralPath $summary -Encoding utf8NoBOM
    $json = & pwsh -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'StallStacks.ps1') -Trace (Join-Path $work 'absent.nettrace') -Summary $summary
    $result = ($json -join "`n") | ConvertFrom-Json
    if ($result.verdict -ne 'CANNOT-READ') { Write-Output "FAIL: verdict $($result.verdict), expected CANNOT-READ (no trace)" }
    elseif ($null -ne $result.run) { Write-Output "FAIL: a summary line with no run field was reported as run $($result.run)" }
    else { Write-Output 'PASSED: the line with no run field is reported with no run'; $code = 0 }
}
finally {
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
}
exit $code

# A plain T-005 summary line has no run field. StallStacks.ps1, asked for no -Run, must not report a run number the line does not
# carry: when the trace is read it reports run null ($line.run); when there is no trace it must say the same, not run 0.
$ErrorActionPreference = 'Stop'
$stacks = Join-Path $PSScriptRoot 'StallStacks.ps1'
$work = Join-Path ([System.IO.Path]::GetTempPath()) ("fsa-stallstacks-plain-{0}" -f [guid]::NewGuid().ToString('N'))
[void][System.IO.Directory]::CreateDirectory($work)
try {
    $summary = Join-Path $work 'runs.jsonl'
    $out = Join-Path $work 'out.json'
    Set-Content -LiteralPath $summary -Value '{"exitReason":"closed","primaryPhase":"scan","phases":[{"name":"scan","reached":true,"longestWaitMs":85}]}' -Encoding utf8NoBOM
    & pwsh -NoProfile -ExecutionPolicy Bypass -File $stacks -Trace (Join-Path $work 'none.nettrace') -Summary $summary -Out $out | Out-Null
    $result = Get-Content -LiteralPath $out -Raw | ConvertFrom-Json
    if ($result.verdict -cne 'CANNOT-READ') { Write-Output "FAIL: verdict $($result.verdict), expected CANNOT-READ"; exit 1 }
    if ($null -ne $result.run) { Write-Output "FAIL: run $($result.run) reported for a summary line with no run field"; exit 1 }
    Write-Output 'PASSED'
    exit 0
}
finally {
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
}
